"""Observability Adapter — CQRS read-projection engine for Native SDD Graphs.

Projects native property graphs into human-readable Markdown spec sheets,
Mermaid architectural diagrams, compliance matrices, and PR delta summaries.
Governed by framework/governance/OBSERVABILITY_ADAPTER_CONTRACT.md (CHG-108, GD-95).
"""

from __future__ import annotations

from .graph_engine import SddGraph

GENERATOR_BANNER = (
    "<!-- ===================================================================== -->\n"
    "<!-- GENERATED BY SDD-RENDER. DO NOT EDIT DIRECTLY. MUTATE THE GRAPH SOURCE. -->\n"
    "<!-- ===================================================================== -->\n\n"
)


class ObservabilityAdapter:
    """Projects SddGraph models into human-readable Markdown and Mermaid views."""

    def render_spec_sheet(self, graph: SddGraph, title: str | None = None) -> str:
        """Render a full human-readable Markdown specification sheet."""
        lines = [GENERATOR_BANNER]
        doc_title = title or (list(graph.slice_ids)[0] if graph.slice_ids else "Specification")
        lines.append(f"# Specification: {doc_title}\n")

        # 0. Metadata & Executive Context (if present)
        meta = getattr(graph, "metadata", {})
        if meta:
            if meta.get("description"):
                lines.append(f"> {meta['description']}\n")

            prob = meta.get("problem_statement")
            if isinstance(prob, dict):
                lines.append("## Executive Problem Context\n")
                if prob.get("problem"):
                    lines.append(f"- **Problem Statement**: {prob['problem']}")
                if prob.get("impact"):
                    lines.append(f"- **Business Impact**: {prob['impact']}")
                if prob.get("opportunity"):
                    lines.append(f"- **Market Opportunity**: {prob['opportunity']}")
                if isinstance(prob.get("current_state"), list):
                    lines.append("- **Current State Pain Points**:")
                    for pt in prob["current_state"]:
                        lines.append(f"  - {pt}")
                lines.append("")

            hyp = meta.get("mvp_hypothesis")
            if isinstance(hyp, dict):
                lines.append("## Core MVP Hypothesis\n")
                if hyp.get("statement"):
                    lines.append(f"- **Hypothesis**: {hyp['statement']}")
                if hyp.get("validation"):
                    lines.append(f"- **Validation Gate**: {hyp['validation']}")
                lines.append("")

        # 1. Executive Summary & Business Objectives
        biz_nodes = graph.nodes_by_type("business_objective")
        if biz_nodes:
            lines.append("## 1. Business Objectives & Strategic Intent\n")
            for b in biz_nodes:
                lines.append(f"### {b.get('title', b['id'])} (`{b['id']}`)\n")
                if b.get("statement"):
                    lines.append(f"- **Objective**: {b['statement']}")
                if b.get("description"):
                    lines.append(f"\n{b['description'].strip()}\n")
                props = b.get("properties", {})
                if props.get("category"):
                    lines.append(f"- **Category**: {props['category']}")
                if props.get("priority"):
                    lines.append(f"- **Priority**: {props['priority']}")
                if props.get("roi_target"):
                    lines.append(f"- **Target ROI / Value**: {props['roi_target']}")
                if props.get("business_driver"):
                    lines.append(f"- **Business Driver**: {props['business_driver']}")
                if props.get("availability_target"):
                    lines.append(f"- **Availability Target**: {props['availability_target']}")
                if props.get("peak_throughput_tps"):
                    lines.append(f"- **Peak Throughput**: {props['peak_throughput_tps']} TPS")

                # Traceability edges from this objective
                out_edges = [e for e in graph.edges if e["from"] == b["id"]]
                for edge in out_edges:
                    rel_title = edge["relation"].replace("_", " ").title()
                    note = edge.get("notes") or edge.get("description")
                    note_str = f" — {note}" if note else ""
                    lines.append(f"- **{rel_title}**: `{edge['to']}`{note_str}")
                lines.append("")

        # 2. Product Capabilities
        cap_nodes = graph.nodes_by_type("product_capability")
        if cap_nodes:
            lines.append("## 2. Product Scope & Container Capabilities\n")
            for c in cap_nodes:
                lines.append(f"### {c.get('title', c['id'])} (`{c['id']}`)\n")
                if c.get("statement"):
                    lines.append(f"- **Capability**: {c['statement']}")
                if c.get("description"):
                    lines.append(f"\n{c['description'].strip()}\n")
                props = c.get("properties", {})
                if props.get("persona"):
                    lines.append(f"- **Target Persona**: {props['persona']}")
                if props.get("priority"):
                    lines.append(f"- **Priority**: {props['priority']}")
                if props.get("release_phase"):
                    lines.append(f"- **Release Phase**: {props['release_phase']}")
                if props.get("feature_flag"):
                    lines.append(f"- **Feature Flag**: `{props['feature_flag']}`")
                sla = props.get("sla_threshold") or props.get("threshold")
                if sla:
                    lines.append(f"- **SLA / Performance Bound**: {sla}")

                story = props.get("user_story")
                if isinstance(story, dict):
                    lines.append(
                        f"\n**User Story**: As a **{story.get('role', 'User')}**, I want to **{story.get('want', '')}**, so that **{story.get('so_that', '')}**.\n"
                    )

                acs = props.get("acceptance_criteria")
                if isinstance(acs, list) and acs:
                    lines.append("**Acceptance Criteria**:")
                    for ac in acs:
                        lines.append(f"- {ac}")
                    lines.append("")

                steps = props.get("interaction_steps")
                if isinstance(steps, list) and steps:
                    lines.append("**User Interaction Steps**:")
                    for step in steps:
                        lines.append(f"- {step}")
                    lines.append("")

                ecs = props.get("edge_cases")
                if isinstance(ecs, list) and ecs:
                    lines.append("**Edge Cases & Fallbacks**:")
                    for ec in ecs:
                        lines.append(f"- {ec}")
                    lines.append("")

                # Relational contracts for this capability
                rel_edges = [e for e in graph.edges if e["from"] == c["id"]]
                for edge in rel_edges:
                    rel_title = edge["relation"].replace("_", " ").title()
                    note = edge.get("notes") or edge.get("description")
                    note_str = f" — {note}" if note else ""
                    lines.append(f"- **{rel_title}**: `{edge['to']}`{note_str}")
                    if edge.get("rationale"):
                        lines.append(f"  - *Rationale*: {edge['rationale']}")

                constraint_edges = [
                    e for e in graph.edges if e["to"] == c["id"] and e["relation"] == "constrains"
                ]
                for edge in constraint_edges:
                    note = edge.get("notes") or edge.get("description")
                    note_str = f" — {note}" if note else ""
                    lines.append(f"- **Constrained by**: `{edge['from']}`{note_str}")
                    if edge.get("rationale"):
                        lines.append(f"  - *Rationale*: {edge['rationale']}")

                lines.append("")

        # 3. Formal Requirements (EARS)
        req_nodes = graph.nodes_by_type("formal_requirement")
        if req_nodes:
            lines.append("## 3. Formal Functional Requirements (EARS)\n")
            for r in req_nodes:
                pattern = r.get("pattern", "ubiquitous")
                lines.append(
                    f"- **`{r['id']}`** [{pattern.upper()}]: {r.get('statement', r.get('title', ''))}"
                )
                if r.get("description"):
                    lines.append(f"  > {r['description'].strip()}")
            lines.append("")

        # 4. Acceptance Criteria & Oracles (BDD)
        bdd_nodes = graph.nodes_by_type("acceptance_scenario")
        if bdd_nodes:
            lines.append("## 4. Acceptance Scenarios & Behavioral Oracles (BDD)\n")
            for s in bdd_nodes:
                lines.append(f"### Scenario: {s.get('title', s['id'])} (`{s['id']}`)\n")
                if s.get("description"):
                    lines.append(f"> {s['description'].strip()}\n")
                lines.append(f"- **Given** {s.get('given', '...')}")
                lines.append(f"- **When** {s.get('when', '...')}")
                lines.append(f"- **Then** {s.get('then', '...')}\n")

        # 5. Architecture Decisions (ADR)
        adr_nodes = graph.nodes_by_type("architectural_decision")
        if adr_nodes:
            lines.append("## 5. Architectural Decisions (ADR)\n")
            for a in adr_nodes:
                lines.append(f"### {a.get('title', a['id'])} (`{a['id']}`)\n")
                if a.get("status"):
                    lines.append(f"- **Status**: {a['status']}")
                if a.get("context"):
                    lines.append(f"- **Context**: {a['context']}")
                if a.get("decision"):
                    lines.append(f"- **Decision**: {a['decision']}")
                if a.get("consequences"):
                    lines.append(f"- **Consequences**: {a['consequences']}")
                if a.get("description"):
                    lines.append(f"\n{a['description'].strip()}\n")
                lines.append("")

        # 6. Implementation & Verification Proofs (TDD/IPLAN)
        tdd_nodes = graph.nodes_by_type("test_fixture")
        task_nodes = graph.nodes_by_type("task_action")
        if tdd_nodes or task_nodes:
            lines.append("## 6. Implementation Tasks & Verification Proofs\n")
            if tdd_nodes:
                lines.append("### Automated Test Fixtures (TDD)")
                for t in tdd_nodes:
                    lines.append(
                        f"- **`{t['id']}`**: `{t.get('command', 'pytest')}` targeting `{t.get('target_file', '')}`"
                    )
                lines.append("")
            if task_nodes:
                lines.append("### Implementation Tasks (IPLAN)")
                for m in task_nodes:
                    if "_rollback" in m["id"]:
                        continue
                    lines.append(
                        f"- **`{m['id']}`** [{m.get('action', 'apply')}]: {m.get('title', '')} (`{m.get('target_file', '')}`)"
                    )
                lines.append("")

        # 7. Evaluation Suites (EVAL)
        eval_nodes = graph.nodes_by_type("evaluation_suite")
        if eval_nodes:
            lines.append("## 7. Evaluation Suites & Quality Gates (EVAL)\n")
            for ev in eval_nodes:
                lines.append(f"### {ev.get('title', ev['id'])} (`{ev['id']}`)\n")
                if ev.get("statement"):
                    lines.append(f"- **Scope**: {ev['statement']}")
                if ev.get("description"):
                    lines.append(f"\n{ev['description'].strip()}\n")
                props = ev.get("properties", {})
                if props.get("quality_gate"):
                    lines.append(f"- **Quality Gate**: {props['quality_gate']}")
                if props.get("benchmark_threshold"):
                    lines.append(f"- **Benchmark Threshold**: {props['benchmark_threshold']}")
                lines.append("")

        return "\n".join(lines).strip() + "\n"

    def render_mermaid(self, graph: SddGraph, diagram_type: str = "lineage") -> str:
        """Render pure text Mermaid diagram from graph structure."""
        lines = ["```mermaid"]

        if diagram_type == "c4-container":
            lines.append("graph TB")
            lines.append('    subgraph Containers["System Containers"]')
            for node in graph.nodes.values():
                if node.get("type") in (
                    "system_container",
                    "product_capability",
                    "component_contract",
                ):
                    clean_title = (node.get("title") or node["id"]).replace('"', "'")
                    lines.append(
                        f'        {node["id"]}["{clean_title}<br/>[{node.get("type", "container")}]"]'
                    )
            lines.append("    end")
        else:
            # Default: Lineage DAG
            lines.append("graph LR")
            for node in graph.nodes.values():
                clean_title = (node.get("title") or node.get("statement") or node["id"]).replace(
                    '"', "'"
                )
                if len(clean_title) > 35:
                    clean_title = clean_title[:32] + "..."
                lines.append(f'    {node["id"]}["{node["id"]}<br/>{clean_title}"]')

        for edge in graph.edges:
            rel = edge.get("relation", "")
            lines.append(f"    {edge['from']} -->|{rel}| {edge['to']}")

        lines.append("```\n")
        return "\n".join(lines)

    def render_matrix(self, graph: SddGraph) -> str:
        """Render traceability verification compliance matrix table."""
        lines = [GENERATOR_BANNER]
        lines.append("# Traceability Verification Matrix\n")
        lines.append("| Requirement (EARS) | BDD Oracle | Test Fixture (TDD) | Status |")
        lines.append("|---|---|---|:---:|")

        reqs = graph.nodes_by_type("formal_requirement")
        for req in reqs:
            rid = req["id"]
            # Find BDD scenarios
            bdds = [
                e["from"] for e in graph.edges if e["to"] == rid and e["relation"] == "verifies"
            ]
            bdd_str = ", ".join(f"`{b}`" for b in bdds) if bdds else "*MISSING*"

            # Find TDD fixtures for those BDDs
            tdds: list[str] = []
            for b in bdds:
                tdds.extend(
                    [e["from"] for e in graph.edges if e["to"] == b and e["relation"] == "proves"]
                )
            tdd_str = ", ".join(f"`{t}`" for t in tdds) if tdds else "*MISSING*"

            status = "✅ PASS" if bdds and tdds else "❌ INCOMPLETE"
            lines.append(f"| `{rid}` | {bdd_str} | {tdd_str} | {status} |")

        return "\n".join(lines) + "\n"

    def render_pr_impact_summary(self, base_graph: SddGraph, head_graph: SddGraph) -> str:
        """Render high-level PR impact comment block for GitHub."""
        added = [nid for nid in head_graph.nodes if nid not in base_graph.nodes]
        modified = [
            nid
            for nid in head_graph.nodes
            if nid in base_graph.nodes and head_graph.nodes[nid] != base_graph.nodes[nid]
        ]
        deleted = [nid for nid in base_graph.nodes if nid not in head_graph.nodes]

        # Calculate combined blast radius
        blast_radius: set[str] = set()
        for nid in added + modified:
            blast_radius.update(head_graph.descendants(nid))

        lines = [
            "### 📊 Native SDD Graph Impact Summary",
            "",
            f"- **Added Nodes**: {len(added)}"
            + (f" (`{', '.join(added[:5])}`...)" if added else ""),
            f"- **Modified Nodes**: {len(modified)}"
            + (f" (`{', '.join(modified[:5])}`...)" if modified else ""),
            f"- **Deleted Nodes**: {len(deleted)}"
            + (f" (`{', '.join(deleted[:5])}`...)" if deleted else ""),
            f"- **Calculated Blast Radius**: {len(blast_radius)} downstream node(s) affected",
            "",
            "<details><summary>Click to view Visual Delta Graph</summary>",
            "",
            self.render_mermaid(head_graph, diagram_type="lineage"),
            "</details>",
        ]
        return "\n".join(lines) + "\n"
